def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find solid lines, then identify the color whose lines form the
    # strongest balanced partition of the grid.
    candidates = {}
    for r in range(h):
        if len(set(grid[r])) == 1:
            candidates.setdefault(grid[r][0], [[], []])[0].append(r)
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.setdefault(grid[0][c], [[], []])[1].append(c)

    def sections(size, dividers):
        bounds = [-1] + sorted(dividers) + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    best = None
    for color, (dr, dc) in candidates.items():
        rs, cs = sections(h, dr), sections(w, dc)
        # Ignore colors that don't produce a meaningful partition.
        if len(rs) == 1 and len(cs) == 1:
            continue
        min_size = min([b - a for a, b in rs] + [b - a for a, b in cs])
        score = (min_size, len(dr) + len(dc))
        if best is None or score > best[0]:
            best = (score, dr, dc)

    if best is None:
        return [row[:] for row in grid]

    _, dr, dc = best
    rs, cs = sections(h, dr), sections(w, dc)
    out = [row[:] for row in grid]

    # The upper-left compartment provides the pattern copied to the others.
    r0, r1 = rs[0]
    c0, c1 = cs[0]
    tile = [grid[r][c0:c1] for r in range(r0, r1)]
    counts = {}
    for row in tile:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    for a, b in rs:
        for x, y in cs:
            if b - a != r1 - r0 or y - x != c1 - c0:
                continue
            for i in range(r1 - r0):
                for j in range(c1 - c0):
                    value = tile[i][j]
                    if value != background:
                        out[a + i][x + j] = value
    return out
